Hi,

I found that this repo doesn't implement the function `scaled_dot_product_attention` on CPU.

![Image](https://github.com/user-attachments/assets/92e7d8ad-cb6b-4b92-9044-bd75dde042b1)

However, when I use the code below to test, I found that it could work. I couldn't explain it. Could you help me please?

```c++
#include <cmath>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

#include "mlx/device.h"
#include "mlx/mlx.h"

namespace mx = mlx::core;

// 辅助函数，将Shape转换为字符串
std::string shape_to_string(const std::vector<int>& shape)
{
    std::string result = "[";
    for (size_t i = 0; i < shape.size(); ++i) {
        result += std::to_string(shape[i]);
        if (i < shape.size() - 1) {
            result += ", ";
        }
    }
    result += "]";
    return result;
}

// 创建加法掩码（additive mask）的辅助函数
mx::array create_additive_mask(int seq_len, bool use_causal_pattern = false, mx::StreamOrDevice s = {})
{
    if (use_causal_pattern) {
        // 因果掩码模式 - 下三角矩阵为0（允许），上三角为大负值（屏蔽）
        auto tri_mask = mx::tril(mx::ones({ seq_len, seq_len }, s));
        // 创建加法掩码：0表示保持原值，-inf表示屏蔽
        return (1.0f - tri_mask) * (-1e9f);
    } else {
        // 这里也可以创建自定义掩码，这里用随机生成的掩码作为示例
        // 生成0和-1e9的随机掩码（只是示例用，实际应用中应该有特定模式）
        auto random_vals = mx::random::normal({ seq_len, seq_len }, std::nullopt, s);
        auto mask = mx::where(random_vals > 0.0f, mx::zeros({ seq_len, seq_len }, s), mx::full({ seq_len, seq_len }, -1e9f, s));
        return mask;
    }
}

// 实现一个朴素的attention计算函数，只使用加法掩码
mx::array naive_scaled_dot_product_attention(
    const mx::array& queries,
    const mx::array& keys,
    const mx::array& values,
    float scale,
    const std::vector<mx::array>& mask_arrs = {})
{
    // 1. 计算注意力分数: Q * K^T
    mx::array scores = mx::matmul(queries, mx::transpose(keys, { 0, 1, 3, 2 }));

    // 2. 应用缩放因子
    scores = scores * scale;

    // 3. 应用掩码 (如果提供)
    if (!mask_arrs.empty()) {
        // 使用提供的掩码数组
        for (const auto& mask_arr : mask_arrs) {
            mx::array expanded_mask = mask_arr;
            // 扩展掩码以匹配scores的形状
            if (mask_arr.ndim() < scores.ndim()) {
                expanded_mask = mx::broadcast_to(
                    mx::reshape(mask_arr, { 1, 1, mask_arr.shape()[0], mask_arr.shape()[1] }),
                    scores.shape());
            }
            // 直接加到注意力分数上
            scores = scores + expanded_mask;
        }
    }

    // 4. 应用softmax获取注意力权重
    mx::array attention_weights = mx::softmax(scores, -1);

    // 5. 计算输出: attention_weights * V
    mx::array output = mx::matmul(attention_weights, values);

    return output;
}

int main()
{
    auto mystream = mx::new_stream(mx::Device::cpu);
    // 基本数组操作示例
    auto x = mx::array({ 1, 2, 3 });
    auto y = mx::array({ 1, 2, 3 });
    std::cout << "基本数组相加: " << x + y << std::endl;

    // 使用scaled_dot_product_attention进行注意力计算
    // 创建查询(q)、键(k)和值(v)矩阵
    // 假设我们有一个批次大小为1，2个注意力头，序列长度为4，每个头的维度为3
    int batch_size = 4;
    int num_heads = 8;
    int seq_len = 1024;
    int head_dim = 64;

    // 初始化形状
    std::vector<int> shape = { batch_size, num_heads, seq_len, head_dim };

    // 随机初始化q、k、v矩阵 - 使用MLX正确的初始化方法
    auto q = mx::random::normal(shape, std::nullopt, mystream);
    auto k = mx::random::normal(shape, std::nullopt, mystream);
    auto v = mx::random::normal(shape, std::nullopt, mystream);

    // 计算缩放因子 (1/sqrt(head_dim))
    float scale = 1.0f / std::sqrt(head_dim);

    std::cout << "Query shape: " << shape_to_string(q.shape()) << std::endl;
    std::cout << "Key shape: " << shape_to_string(k.shape()) << std::endl;
    std::cout << "Value shape: " << shape_to_string(v.shape()) << std::endl;

    // 创建显式的加法掩码 - 使用因果模式作为示例
    mx::array additive_mask = create_additive_mask(seq_len, true, mystream);
    std::cout << "加法掩码 (4x4):\n";
    mx::eval(additive_mask);
    std::stringstream ss_mask;
    ss_mask << additive_mask;
    std::cout << ss_mask.str() << std::endl;

    // 准备掩码数组
    std::vector<mx::array> mask_arrs = { additive_mask };

    // 调用MLX的scaled_dot_product_attention函数
    // 注意：现在我们传递空字符串作为mask_mode，而是使用mask_arrs
    // 开始计时
    auto total_duration = 0.0;
    auto test_times = 1000;
    for (int i = 0; i < test_times; i++) {
        auto start_time = std::chrono::high_resolution_clock::now();
        auto tmpresult = mx::fast::scaled_dot_product_attention(
            q, k, v, scale, "", mask_arrs, mystream);
        mx::eval(tmpresult);
        auto end_time = std::chrono::high_resolution_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end_time - start_time);
        total_duration += duration.count();
        std::cout << "第" << i << "次计算耗时: " << duration.count() << " 毫秒" << std::endl;
    }

    // 结束计时
    std::cout << "执行注意力平均计算耗时: " << total_duration << " 毫秒" << std::endl;
    auto mlx_attention_output = mx::fast::scaled_dot_product_attention(
        q, k, v, scale, "", mask_arrs, mystream);

    std::cout << "MLX attention output shape: " << shape_to_string(mlx_attention_output.shape()) << std::endl;

    // 调用我们自己实现的naive scaled_dot_product_attention
    auto naive_attention_output = naive_scaled_dot_product_attention(
        q, k, v, scale, mask_arrs);

    std::cout << "Naive attention output shape: " << shape_to_string(naive_attention_output.shape()) << std::endl;

    // 对比两个输出的差异
    mx::array diff = mx::abs(mlx_attention_output - naive_attention_output);
    mx::array max_diff = mx::max(diff);
    mx::array mean_diff = mx::mean(diff);

    // 确保计算完成
    mx::eval(max_diff, mean_diff);

    std::cout << "最大差异: " << max_diff << std::endl;
    std::cout << "平均差异: " << mean_diff << std::endl;

    // 打印部分输出结果
    if (mlx_attention_output.size() > 0) {
        std::cout << "MLX attention output 第一个值: " << std::endl;
        auto mlx_first_values = mx::slice(
            mlx_attention_output,
            { 0, 0, 0, 0 }, // 起始索引
            { 1, 1, 1, std::min(3, head_dim) } // 结束索引
        );

        std::cout << "Naive attention output 第一个值: " << std::endl;
        auto naive_first_values = mx::slice(
            naive_attention_output,
            { 0, 0, 0, 0 }, // 起始索引
            { 1, 1, 1, std::min(3, head_dim) } // 结束索引
        );

        // 确保计算完成
        mx::eval(mlx_first_values, naive_first_values);

        // 将数组转换为字符串
        std::stringstream ss_mlx, ss_naive;
        ss_mlx << mlx_first_values;
        ss_naive << naive_first_values;
        std::cout << "MLX: " << ss_mlx.str() << std::endl;
        std::cout << "Naive: " << ss_naive.str() << std::endl;
    }

    return 0;
}
```
